var t=typeof(UnityEngine.SceneManagement.Scene);return string.Join(";",System.Array.ConvertAll(t.GetMethods(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Static).Where(m=>m.Name.ToLower().Contains("dirty")||m.Name.ToLower().Contains("clean")).ToArray(),m=>m.ToString()+" public="+m.IsPublic+" assembly="+m.IsAssembly))+";props="+string.Join(";",System.Array.ConvertAll(t.GetProperties(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Static).Where(p=>p.Name.ToLower().Contains("dirty")).ToArray(),p=>p.Name+" setter="+(p.GetSetMethod(true)!=null)));
